"""Internal compressed core for deterministic RQ1-C protocol probes.

Direct script execution is intentionally routed through the public exact-head entrypoint.
Imports restore the reviewed protocol core source after an integrity check.
"""

from __future__ import annotations

import base64
import hashlib
import sys
import zlib
from pathlib import Path

_REPO_ROOT = Path(__file__).resolve().parents[1]
if str(_REPO_ROOT) not in sys.path:
    sys.path.insert(0, str(_REPO_ROOT))

if __name__ == "__main__":
    from tools.run_rq1c_protocol_probes import main as guarded_main

    raise SystemExit(guarded_main())

_SOURCE_SHA256 = "ed37d4f347efc57e5ae98f2d63a2f51b6ec35fe0fcceb88eb60db4dcecef4735"
_COMPRESSED_SOURCE_B64 = """"""

_source = zlib.decompress(base64.b64decode(_COMPRESSED_SOURCE_B64))
if hashlib.sha256(_source).hexdigest() != _SOURCE_SHA256:
    raise RuntimeError("RQ1-C protocol core payload integrity mismatch")
exec(compile(_source, __file__, "exec"), globals(), globals())
